<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import PageHeader from "@/components/PageHeader.vue";
import DataGrid, { type GridColumn } from "@/components/DataGrid.vue";
import { ApiError } from "@/services/http";
import { useAuthSession } from "@/composables/useAuthSession";
import { createTarjeta, getTarjetaOptions, isAssignmentVigente, listTarjetas, type Tarjeta, type TarjetaOptions } from "@/services/tarjetas";

const route = useRoute(); const router = useRouter(); const session = useAuthSession();
const beneficiaryId = computed(() => { const raw = route.query.beneficiario; const value = Number(Array.isArray(raw) ? raw[0] : raw); return Number.isInteger(value) && value > 0 ? value : undefined; });
const cards = ref<Tarjeta[]>([]); const options = ref<TarjetaOptions>({ estadosTarjeta: [], tiposTarjeta: [], tiposVigencia: [], estadosAsignacion: [], beneficiarios: [], solicitudes: [] });
const search = ref(""); const estado = ref<"all" | "active" | "inactive">("all"); const page = ref(1); const pagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 });
const loading = ref(false); const saving = ref(false); const error = ref(""); const success = ref(""); const showCardForm = ref(false);
const cardForm = ref({ codigoTarjeta: "", codigoExterno: "", numeroSerie: "", idEstadoTarjeta: 0, idTipoTarjeta: null as number | null, fechaAdquisicion: "", fechaAlta: new Date().toISOString().slice(0, 10), fechaBaja: "", motivoBaja: "", requiereRevision: false, observacionTarjeta: "" });
const columns: GridColumn[] = [{ key: "tarjeta", label: "Tarjeta", width: "17%" }, { key: "nombreEstadoTarjeta", label: "Estado administrativo", width: "16%" }, { key: "asignacion", label: "Asignación vigente", width: "16%" }, { key: "nombreBeneficiario", label: "Beneficiario", width: "17%" }, { key: "perfilesAcceso", label: "Perfil", width: "14%" }, { key: "vigencia", label: "Vigencia", width: "20%" }];
const message = (e: unknown) => e instanceof ApiError ? e.message : "Ocurrió un error inesperado";
const can = (permission: string) => session.user.value?.permissions.includes(permission) ?? false;
const cardFormValid = computed(() => Boolean(cardForm.value.codigoTarjeta && cardForm.value.idEstadoTarjeta > 0 && cardForm.value.fechaAlta));
function row(card: Tarjeta): Record<string, unknown> { const hasCurrentAssignment = isAssignmentVigente(card.esAsignacionVigente) && card.idAsignacion !== null; return { ...card, tarjeta: card.codigoTarjeta, asignacion: hasCurrentAssignment ? (card.nombreEstadoAsignacion ?? "Asignada") : "Disponible", vigencia: hasCurrentAssignment ? `${card.fechaInicioVigencia?.slice(0, 10)} — ${card.fechaFinVigencia?.slice(0, 10) ?? "Sin vencimiento"}` : "—" }; }
async function load() { loading.value = true; error.value = ""; try { const result = await listTarjetas(search.value, page.value, estado.value, beneficiaryId.value); cards.value = result.items; pagination.value = result.pagination; } catch (e) { error.value = message(e); } finally { loading.value = false; } }
async function loadOptions() { try { options.value = await getTarjetaOptions(); } catch (e) { error.value = message(e); } }
function resetCardForm() { cardForm.value = { codigoTarjeta: "", codigoExterno: "", numeroSerie: "", idEstadoTarjeta: 0, idTipoTarjeta: null, fechaAdquisicion: "", fechaAlta: new Date().toISOString().slice(0, 10), fechaBaja: "", motivoBaja: "", requiereRevision: false, observacionTarjeta: "" }; showCardForm.value = true; }
function date(value: string) { return value ? new Date(`${value}T00:00:00`) : null; }
async function saveCard() { if (!cardFormValid.value) return; saving.value = true; error.value = ""; try { await createTarjeta({ ...cardForm.value, codigoExterno: cardForm.value.codigoExterno || null, numeroSerie: cardForm.value.numeroSerie || null, fechaAdquisicion: date(cardForm.value.fechaAdquisicion), fechaAlta: date(cardForm.value.fechaAlta)!, fechaBaja: date(cardForm.value.fechaBaja), motivoBaja: cardForm.value.motivoBaja || null, observacionTarjeta: cardForm.value.observacionTarjeta || null, assignment: null }); showCardForm.value = false; success.value = "Tarjeta registrada correctamente."; page.value = 1; await load(); } catch (e) { error.value = message(e); } finally { saving.value = false; } }
function changePage(next: number) { page.value = next; void load(); }
onMounted(() => { void Promise.all([load(), loadOptions(), session.restore()]); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Operación', to: '/' }, { label: 'Tarjetas' }]" />
  <PageHeader eyebrow="Operación" title="Tarjetas" description="Registro lógico de tarjetas SIGA y gestión de sus asignaciones." :action-label="can('TARJETAS_ASIGNAR') ? 'Nueva tarjeta' : undefined" @action="resetCardForm" />
  <div v-if="success" class="bo-notice bo-notice-success">{{ success }}</div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="page = 1; load()"><input v-model="search" placeholder="Buscar por código, serie o beneficiario..." aria-label="Buscar tarjetas" /><select v-model="estado" aria-label="Filtrar estado"><option value="all">Todos los estados</option><option value="active">Activas</option><option value="inactive">Inactivas</option></select><button class="bo-btn bo-btn-primary">Filtrar</button></form><p v-if="beneficiaryId" class="bo-form-note">Mostrando tarjetas del beneficiario seleccionado.</p><DataGrid :columns="columns" :rows="cards.map(row)" :row-key="item => String(item.idTarjeta)" :pagination="pagination" :loading="loading" :error="error" empty-text="No hay tarjetas registradas." @page="changePage"><template #cell-tarjeta="{ row }"><span class="tarjeta-card-cell"><strong>{{ row.codigoTarjeta }}</strong><small>Serie: {{ row.numeroSerie ?? row.codigoExterno ?? "Sin referencia adicional" }}</small></span></template><template #cell-nombreEstadoTarjeta="{ row }">{{ row.nombreEstadoTarjeta }}</template><template #cell-asignacion="{ row }"><span class="status-badge" :class="{ 'status-badge--inactive': !row.idAsignacion }">{{ row.asignacion }}</span></template><template #cell-nombreBeneficiario="{ row }">{{ row.nombreBeneficiario ?? "—" }}</template><template #cell-perfilesAcceso="{ row }">{{ row.perfilesAcceso ?? "—" }}</template><template #cell-vigencia="{ row }">{{ row.vigencia }}</template><template #actions="{ row }"><button class="bo-action" @click="router.push({ path: `/tarjetas/${row.idTarjeta}/gestionar`, query: beneficiaryId ? { beneficiario: String(beneficiaryId) } : undefined })">Gestionar</button></template></DataGrid></section>
  <div v-if="showCardForm" class="bo-modal-backdrop" @click.self="showCardForm = false"><section class="bo-modal"><header><div><span class="bo-eyebrow">Registro lógico SIGA</span><h2>Nueva tarjeta</h2></div><button class="bo-close" type="button" @click="showCardForm = false">×</button></header><form class="bo-form" @submit.prevent="saveCard"><div class="bo-form-grid"><label>Código de tarjeta *<input v-model="cardForm.codigoTarjeta" maxlength="30" required /></label><label>Estado de tarjeta *<select v-model.number="cardForm.idEstadoTarjeta" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.estadosTarjeta" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.codigoTipoValor }} · {{ item.nombreTipoValor }}</option></select></label><label>Tipo de tarjeta<select v-model="cardForm.idTipoTarjeta"><option :value="null">Sin tipo</option><option v-for="item in options.tiposTarjeta" :key="item.idTipoTarjeta" :value="item.idTipoTarjeta">{{ item.nombreTipoTarjeta }}</option></select></label><label>Número de serie<input v-model="cardForm.numeroSerie" maxlength="100" /></label><label>Código externo<input v-model="cardForm.codigoExterno" maxlength="50" /></label><label>Fecha de alta *<input v-model="cardForm.fechaAlta" type="date" required /></label><label>Fecha de adquisición<input v-model="cardForm.fechaAdquisicion" type="date" /></label><label>Fecha de baja<input v-model="cardForm.fechaBaja" type="date" /></label><label class="bo-form-wide">Motivo de baja<textarea v-model="cardForm.motivoBaja" maxlength="500" rows="2" /></label><label class="bo-form-wide"><input v-model="cardForm.requiereRevision" type="checkbox" /> Requiere revisión</label><label class="bo-form-wide">Observación<textarea v-model="cardForm.observacionTarjeta" maxlength="1000" rows="2" /></label></div><footer class="bo-modal-actions"><button type="button" class="bo-btn" @click="showCardForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving || !cardFormValid">{{ saving ? "Guardando..." : "Registrar tarjeta" }}</button></footer></form></section></div>
</template>
